window.GAOKAO_PAPERS=window.GAOKAO_PAPERS||{};window.GAOKAO_PAPERS["2022-shanghai"]=[{"id":"2022-shanghai-q01","paperId":"2022-shanghai","number":1,"type":"fill","score":4,"lessonIds":["7.2"],"difficulty":"基础","hint":"把括号里的实部和虚部都乘2。","legacy":false,"legacyReason":"","searchText":"若复数 z=1+\\i （其中 \\i 为虚数单位），则 2z=\\fillinblank{} . ","questionHtml":"若复数 <span class=\"gk-math\" data-tex=\"z=1+\\i\">z=1+\\i</span>（其中 <span class=\"gk-math\" data-tex=\"\\i\">\\i</span> 为虚数单位），则 <span class=\"gk-math\" data-tex=\"2z=\\fillinblank{}\">2z=\\fillinblank{}</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"2+2\\i\">2+2\\i</span>","answerKey":"","solutionHtml":"<span class=\"gk-math\" data-tex=\"2z=2(1+\\i)=2+2\\i\">2z=2(1+\\i)=2+2\\i</span>. 实部与虚部都乘2即可。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q02","paperId":"2022-shanghai","number":2,"type":"fill","score":4,"lessonIds":["e1-3.2"],"difficulty":"基础","hint":"先认出a²=9，再记住实轴长是2a。","legacy":false,"legacyReason":"","searchText":"双曲线 \\frac{x^2}{9}-y^2=1 的实轴长为 ________ . ","questionHtml":"双曲线 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{9}-y^2=1\">\\frac{x^2}{9}-y^2=1</span> 的实轴长为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"6\">6</span>","answerKey":"","solutionHtml":"双曲线标准式为<span class=\"gk-math\" data-tex=\"x^2/a^2-y^2/b^2=1\">x^2/a^2-y^2/b^2=1</span>，由<span class=\"gk-math\" data-tex=\"a^2=9\">a^2=9</span>得<span class=\"gk-math\" data-tex=\"a=3\">a=3</span>，所以实轴长<span class=\"gk-math\" data-tex=\"2a=6\">2a=6</span>。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q03","paperId":"2022-shanghai","number":3,"type":"fill","score":4,"lessonIds":["5.5","5.4"],"difficulty":"基础","hint":"先用cos²x−sin²x=cos2x把式子变短。","legacy":false,"legacyReason":"","searchText":"函数 y=\\cos^2x-\\sin^2x+1 的最小正周期为 ________ . ","questionHtml":"函数 <span class=\"gk-math\" data-tex=\"y=\\cos^2x-\\sin^2x+1\">y=\\cos^2x-\\sin^2x+1</span> 的最小正周期为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\pi\">\\pi</span>","answerKey":"","solutionHtml":"由二倍角公式，<span class=\"gk-math\" data-tex=\"y=\\cos 2x+1\">y=\\cos 2x+1</span>。上下平移不改变周期，故最小正周期为<span class=\"gk-math\" data-tex=\"2\\pi/2=\\pi\">2\\pi/2=\\pi</span>。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q04","paperId":"2022-shanghai","number":4,"type":"fill","score":4,"lessonIds":["2.1"],"difficulty":"基础","hint":"二阶行列式按“左上乘右下，减去右上乘左下”展开。","legacy":true,"legacyReason":"上海地方课程中的二阶行列式，不在本网站五册人教A版的主要知识范围内。","searchText":"设 a 为常数，若行列式 \\begin{vmatrix}a&1\\\\3&2\\end{vmatrix} 的值与行列式 \\begin{vmatrix}a&0\\\\4&1\\end{vmatrix} 的值相等，则 a=\\fillinblank{} . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"a\">a</span> 为常数，若行列式 <span class=\"gk-math\" data-tex=\"\\begin{vmatrix}a&amp;1\\\\3&amp;2\\end{vmatrix}\">\\begin{vmatrix}a&amp;1\\\\3&amp;2\\end{vmatrix}</span> 的值与行列式 <span class=\"gk-math\" data-tex=\"\\begin{vmatrix}a&amp;0\\\\4&amp;1\\end{vmatrix}\">\\begin{vmatrix}a&amp;0\\\\4&amp;1\\end{vmatrix}</span> 的值相等，则 <span class=\"gk-math\" data-tex=\"a=\\fillinblank{}\">a=\\fillinblank{}</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"3\">3</span>","answerKey":"","solutionHtml":"二阶行列式按<span class=\"gk-math\" data-tex=\"\\begin{vmatrix}p&amp;q\\\\r&amp;s\\end{vmatrix}=ps-qr\">\\begin{vmatrix}p&amp;q\\\\r&amp;s\\end{vmatrix}=ps-qr</span>计算。题设化为<span class=\"gk-math\" data-tex=\"2a-3=a\">2a-3=a</span>，解得<span class=\"gk-math\" data-tex=\"a=3\">a=3</span>。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q05","paperId":"2022-shanghai","number":5,"type":"fill","score":4,"lessonIds":["8.3"],"difficulty":"基础","hint":"由底面积9π先求底面半径，再把底面周长乘高。","legacy":false,"legacyReason":"","searchText":"若圆柱的高为 4 ，底面积为 9\\pi ，则该圆柱的侧面积为 ________ . ","questionHtml":"若圆柱的高为 <span class=\"gk-math\" data-tex=\"4\">4</span>，底面积为 <span class=\"gk-math\" data-tex=\"9\\pi\">9\\pi</span>，则该圆柱的侧面积为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"24\\pi\">24\\pi</span>","answerKey":"","solutionHtml":"设底面半径为<span class=\"gk-math\" data-tex=\"r\">r</span>，则<span class=\"gk-math\" data-tex=\"\\pi r^2=9\\pi\">\\pi r^2=9\\pi</span>，所以<span class=\"gk-math\" data-tex=\"r=3\">r=3</span>。圆柱侧面展开成长方形，其面积为底面周长乘高，即<span class=\"gk-math\" data-tex=\"2\\pi rh=2\\pi\\times3\\times4=24\\pi\">2\\pi rh=2\\pi\\times3\\times4=24\\pi</span>。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q06","paperId":"2022-shanghai","number":6,"type":"fill","score":4,"lessonIds":["2.1"],"difficulty":"进阶","hint":"把x+2y拆成(x+y)+y，再由两条条件看y最小能到哪里。","legacy":true,"legacyReason":"涉及二元一次不等式与简单线性规划，可作地方卷拓展；五册课程未单列这一专题。","searchText":"若实数 x ， y 满足 x-y\\le0 ， x+y-1\\ge0 ，则 z=x+2y 的最小值为 ________ . ","questionHtml":"若实数 <span class=\"gk-math\" data-tex=\"x\">x</span>，<span class=\"gk-math\" data-tex=\"y\">y</span> 满足 <span class=\"gk-math\" data-tex=\"x-y\\le0\">x-y\\le0</span>，<span class=\"gk-math\" data-tex=\"x+y-1\\ge0\">x+y-1\\ge0</span>，则 <span class=\"gk-math\" data-tex=\"z=x+2y\">z=x+2y</span> 的最小值为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\frac32\">\\frac32</span>","answerKey":"","solutionHtml":"由<span class=\"gk-math\" data-tex=\"x\\le y\">x\\le y</span>及<span class=\"gk-math\" data-tex=\"x+y\\ge1\">x+y\\ge1</span>，有<span class=\"gk-math\" data-tex=\"2y\\ge x+y\\ge1\">2y\\ge x+y\\ge1</span>，所以<span class=\"gk-math\" data-tex=\"y\\ge\\frac12\">y\\ge\\frac12</span>。于是<span class=\"gk-math\" data-tex=\"z=(x+y)+y\\ge1+\\frac12=\\frac32\">z=(x+y)+y\\ge1+\\frac12=\\frac32</span>。取<span class=\"gk-math\" data-tex=\"x=y=\\frac12\">x=y=\\frac12</span>满足条件并取到等号，故最小值为<span class=\"gk-math\" data-tex=\"\\frac32\">\\frac32</span>。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q07","paperId":"2022-shanghai","number":7,"type":"fill","score":5,"lessonIds":["e3-6.3"],"difficulty":"进阶","hint":"分别写出常数项3ⁿ和x²项的系数，再列出它们的倍数关系。","legacy":false,"legacyReason":"","searchText":"在 (3+x)^n 的二项展开式中，若 x^2 的系数是常数项的 5 倍，则 n=\\fillinblank{} . ","questionHtml":"在 <span class=\"gk-math\" data-tex=\"(3+x)^n\">(3+x)^n</span> 的二项展开式中，若 <span class=\"gk-math\" data-tex=\"x^2\">x^2</span> 的系数是常数项的 <span class=\"gk-math\" data-tex=\"5\">5</span> 倍，则 <span class=\"gk-math\" data-tex=\"n=\\fillinblank{}\">n=\\fillinblank{}</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"10\">10</span>","answerKey":"","solutionHtml":"常数项为<span class=\"gk-math\" data-tex=\"3^n\">3^n</span>，<span class=\"gk-math\" data-tex=\"x^2\">x^2</span>项系数为<span class=\"gk-math\" data-tex=\"\\mathrm C_n^2 3^{n-2}\">\\mathrm C_n^2 3^{n-2}</span>。因此<span class=\"gk-math\" data-tex=\"\\mathrm C_n^2 3^{n-2}=5\\times3^n\">\\mathrm C_n^2 3^{n-2}=5\\times3^n</span>，即<span class=\"gk-math\" data-tex=\"n(n-1)/2=45\">n(n-1)/2=45</span>。解得<span class=\"gk-math\" data-tex=\"n=10\">n=10</span>或<span class=\"gk-math\" data-tex=\"n=-9\">n=-9</span>，取正整数<span class=\"gk-math\" data-tex=\"n=10\">n=10</span>。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q08","paperId":"2022-shanghai","number":8,"type":"fill","score":5,"lessonIds":["3.2"],"difficulty":"进阶","hint":"取x>0，用f(−x)=−f(x)，比较x的系数与常数项。","legacy":false,"legacyReason":"","searchText":"已知 f(x) 为奇函数，且 f(x)=\\begin{cases} a^2x-1, & x<0,\\\\ x+a, & x>0, \\end{cases} 则实数 a=\\fillinblank{} . ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 为奇函数，且 <span class=\"gk-math\" data-tex=\"f(x)=\\begin{cases}\na^2x-1, &amp; x&lt;0,\\\\\nx+a, &amp; x&gt;0,\n\\end{cases}\">f(x)=\\begin{cases}\na^2x-1, &amp; x&lt;0,\\\\\nx+a, &amp; x&gt;0,\n\\end{cases}</span> 则实数 <span class=\"gk-math\" data-tex=\"a=\\fillinblank{}\">a=\\fillinblank{}</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"1\">1</span>","answerKey":"","solutionHtml":"取<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>，则<span class=\"gk-math\" data-tex=\"f(x)=x+a\">f(x)=x+a</span>，<span class=\"gk-math\" data-tex=\"f(-x)=-a^2x-1\">f(-x)=-a^2x-1</span>。奇函数满足<span class=\"gk-math\" data-tex=\"f(-x)=-f(x)=-x-a\">f(-x)=-f(x)=-x-a</span>，对所有<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>比较系数得<span class=\"gk-math\" data-tex=\"a^2=1\">a^2=1</span>且<span class=\"gk-math\" data-tex=\"a=1\">a=1</span>。所以<span class=\"gk-math\" data-tex=\"a=1\">a=1</span>。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q09","paperId":"2022-shanghai","number":9,"type":"fill","score":5,"lessonIds":["e3-6.2","10.1"],"difficulty":"进阶","hint":"游泳只有1项，所以必须选它；其余3项要同时含球类和田径类。","legacy":false,"legacyReason":"","searchText":"为了检测学生的身体素质指标，需从游泳类 1 项，球类 3 项，田径类 4 项，共 8 项项目中随机抽取 4 项进行测试，每一类都被抽到的概率为 ________ （结果用最简分数表示）. ","questionHtml":"为了检测学生的身体素质指标，需从游泳类 <span class=\"gk-math\" data-tex=\"1\">1</span> 项，球类 <span class=\"gk-math\" data-tex=\"3\">3</span> 项，田径类 <span class=\"gk-math\" data-tex=\"4\">4</span> 项，共 <span class=\"gk-math\" data-tex=\"8\">8</span> 项项目中随机抽取 <span class=\"gk-math\" data-tex=\"4\">4</span> 项进行测试，每一类都被抽到的概率为<span class=\"gk-blank\" aria-label=\"填空\">________</span>（结果用最简分数表示）.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\frac37\">\\frac37</span>","answerKey":"","solutionHtml":"总取法有<span class=\"gk-math\" data-tex=\"\\mathrm C_8^4=70\">\\mathrm C_8^4=70</span>种。游泳只有1项，必须被抽到；另外3项从7项中选，且不能全是球类或全是田径类。合适取法为<span class=\"gk-math\" data-tex=\"\\mathrm C_7^3-\\mathrm C_3^3-\\mathrm C_4^3=35-1-4=30\">\\mathrm C_7^3-\\mathrm C_3^3-\\mathrm C_4^3=35-1-4=30</span>。故概率为<span class=\"gk-math\" data-tex=\"30/70=3/7\">30/70=3/7</span>。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q10","paperId":"2022-shanghai","number":10,"type":"fill","score":5,"lessonIds":["e2-4.2"],"difficulty":"挑战","hint":"由S₅=0先解a₁与公差d的关系，把Sₙ写成关于n的二次式。","legacy":false,"legacyReason":"","searchText":"已知等差数列 \\{a_n\\} 的公差不为零， S_n 为其前 n 项和. 若 S_5=0 ，则 S_1 ， S_2 ，…， S_{100} 这 100 个数中所有不同数值的个数为 ________ . ","questionHtml":"已知等差数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的公差不为零，<span class=\"gk-math\" data-tex=\"S_n\">S_n</span> 为其前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和. 若 <span class=\"gk-math\" data-tex=\"S_5=0\">S_5=0</span>，则 <span class=\"gk-math\" data-tex=\"S_1\">S_1</span>，<span class=\"gk-math\" data-tex=\"S_2\">S_2</span>，…，<span class=\"gk-math\" data-tex=\"S_{100}\">S_{100}</span> 这 <span class=\"gk-math\" data-tex=\"100\">100</span> 个数中所有不同数值的个数为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"98\">98</span>","answerKey":"","solutionHtml":"由<span class=\"gk-math\" data-tex=\"S_5=5a_1+10d=0\">S_5=5a_1+10d=0</span>得<span class=\"gk-math\" data-tex=\"a_1=-2d\">a_1=-2d</span>，其中<span class=\"gk-math\" data-tex=\"d\\ne0\">d\\ne0</span>。所以<span class=\"gk-math\" data-tex=\"S_n=na_1+\\frac{n(n-1)}2d=\\frac d2 n(n-5)\">S_n=na_1+\\frac{n(n-1)}2d=\\frac d2 n(n-5)</span>。若<span class=\"gk-math\" data-tex=\"S_n=S_m\">S_n=S_m</span>且<span class=\"gk-math\" data-tex=\"n\\ne m\">n\\ne m</span>，则<span class=\"gk-math\" data-tex=\"(n-m)(n+m-5)=0\">(n-m)(n+m-5)=0</span>，故<span class=\"gk-math\" data-tex=\"n+m=5\">n+m=5</span>。在1到100中，只有<span class=\"gk-math\" data-tex=\"\\{1,4\\}\">\\{1,4\\}</span>、<span class=\"gk-math\" data-tex=\"\\{2,3\\}\">\\{2,3\\}</span>两对重复，其余各不相同，因此不同数值共有<span class=\"gk-math\" data-tex=\"100-2=98\">100-2=98</span>个。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q11","paperId":"2022-shanghai","number":11,"type":"fill","score":5,"lessonIds":["6.3"],"difficulty":"进阶","hint":"把互相垂直的向量a、b放在横纵坐标方向上，用数量积求c的两个坐标。","legacy":false,"legacyReason":"","searchText":"已知平面非零向量 \\bs{a} ， \\bs{b} ， \\bs{c} 的模均为 \\lambda ，若 \\bs{a}\\cdot\\bs{b}=0 ， \\bs{a}\\cdot\\bs{c}=2 ， \\bs{b}\\cdot\\bs{c}=1 ，则 \\lambda=\\fillinblank{} . ","questionHtml":"已知平面非零向量 <span class=\"gk-math\" data-tex=\"\\bs{a}\">\\bs{a}</span>，<span class=\"gk-math\" data-tex=\"\\bs{b}\">\\bs{b}</span>，<span class=\"gk-math\" data-tex=\"\\bs{c}\">\\bs{c}</span> 的模均为 <span class=\"gk-math\" data-tex=\"\\lambda\">\\lambda</span>，若 <span class=\"gk-math\" data-tex=\"\\bs{a}\\cdot\\bs{b}=0\">\\bs{a}\\cdot\\bs{b}=0</span>，<span class=\"gk-math\" data-tex=\"\\bs{a}\\cdot\\bs{c}=2\">\\bs{a}\\cdot\\bs{c}=2</span>，<span class=\"gk-math\" data-tex=\"\\bs{b}\\cdot\\bs{c}=1\">\\bs{b}\\cdot\\bs{c}=1</span>，则 <span class=\"gk-math\" data-tex=\"\\lambda=\\fillinblank{}\">\\lambda=\\fillinblank{}</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\sqrt[4]{5}\">\\sqrt[4]{5}</span>","answerKey":"","solutionHtml":"设<span class=\"gk-math\" data-tex=\"\\bs a=(\\lambda,0)\">\\bs a=(\\lambda,0)</span>、<span class=\"gk-math\" data-tex=\"\\bs b=(0,\\lambda)\">\\bs b=(0,\\lambda)</span>，<span class=\"gk-math\" data-tex=\"\\bs c=(u,v)\">\\bs c=(u,v)</span>。数量积给出<span class=\"gk-math\" data-tex=\"\\lambda u=2\">\\lambda u=2</span>、<span class=\"gk-math\" data-tex=\"\\lambda v=1\">\\lambda v=1</span>，故<span class=\"gk-math\" data-tex=\"u=2/\\lambda\">u=2/\\lambda</span>、<span class=\"gk-math\" data-tex=\"v=1/\\lambda\">v=1/\\lambda</span>。再由<span class=\"gk-math\" data-tex=\"|\\bs c|=\\lambda\">|\\bs c|=\\lambda</span>，得<span class=\"gk-math\" data-tex=\"u^2+v^2=\\lambda^2\">u^2+v^2=\\lambda^2</span>，即<span class=\"gk-math\" data-tex=\"5/\\lambda^2=\\lambda^2\">5/\\lambda^2=\\lambda^2</span>。由于<span class=\"gk-math\" data-tex=\"\\lambda&gt;0\">\\lambda&gt;0</span>，故<span class=\"gk-math\" data-tex=\"\\lambda=\\sqrt[4]5\">\\lambda=\\sqrt[4]5</span>。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q12","paperId":"2022-shanghai","number":12,"type":"fill","score":5,"lessonIds":["3.1","3.2"],"difficulty":"挑战","hint":"令T(x)=1/(x+1)，先找到T(x)=x的正解，再看大于它的x会被送到哪里。","legacy":false,"legacyReason":"","searchText":"设函数 y=f(x) ，定义域为 [0,+\\infty) ，值域为 A ，且对定义域中任意实数 x 都成立 f(x)=f\\left(\\frac1{x+1}\\right) . 若 \\{y\\mid y=f(x),x\\in[0,a]\\}=A ，则实数 a 的取值范围是 ________ . ","questionHtml":"设函数 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span>，定义域为 <span class=\"gk-math\" data-tex=\"[0,+\\infty)\">[0,+\\infty)</span>，值域为 <span class=\"gk-math\" data-tex=\"A\">A</span>，且对定义域中任意实数 <span class=\"gk-math\" data-tex=\"x\">x</span> 都成立 <span class=\"gk-math\" data-tex=\"f(x)=f\\left(\\frac1{x+1}\\right)\">f(x)=f\\left(\\frac1{x+1}\\right)</span>. 若 <span class=\"gk-math\" data-tex=\"\\{y\\mid y=f(x),x\\in[0,a]\\}=A\">\\{y\\mid y=f(x),x\\in[0,a]\\}=A</span>，则实数 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围是<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\left[\\frac{\\sqrt5-1}{2},+\\infty\\right)\">\\left[\\frac{\\sqrt5-1}{2},+\\infty\\right)</span>","answerKey":"","solutionHtml":"令<span class=\"gk-math\" data-tex=\"T(x)=1/(x+1)\">T(x)=1/(x+1)</span>。正的不动点为<span class=\"gk-math\" data-tex=\"\\alpha=(\\sqrt5-1)/2\">\\alpha=(\\sqrt5-1)/2</span>。当<span class=\"gk-math\" data-tex=\"x\\ge\\alpha\">x\\ge\\alpha</span>时，<span class=\"gk-math\" data-tex=\"0&lt;T(x)\\le\\alpha\">0&lt;T(x)\\le\\alpha</span>，且<span class=\"gk-math\" data-tex=\"f(x)=f(T(x))\">f(x)=f(T(x))</span>，所以整个定义域的每个函数值都能在<span class=\"gk-math\" data-tex=\"[0,\\alpha]\">[0,\\alpha]</span>上取得。因此<span class=\"gk-math\" data-tex=\"a\\ge\\alpha\">a\\ge\\alpha</span>足以保证题设值域相等。 若<span class=\"gk-math\" data-tex=\"0\\le a&lt;\\alpha\">0\\le a&lt;\\alpha</span>，取<span class=\"gk-math\" data-tex=\"f(x)=1\">f(x)=1</span>（<span class=\"gk-math\" data-tex=\"x=\\alpha\">x=\\alpha</span>时），其他点取0。由于<span class=\"gk-math\" data-tex=\"T(x)=\\alpha\">T(x)=\\alpha</span>当且仅当<span class=\"gk-math\" data-tex=\"x=\\alpha\">x=\\alpha</span>，这个函数满足题设关系，但<span class=\"gk-math\" data-tex=\"[0,a]\">[0,a]</span>取不到函数值1，不能保证与整个值域相等。因此按“保证对满足条件的函数都成立”的通常命题理解，答案为<span class=\"gk-math\" data-tex=\"[\\alpha,+\\infty)\">[\\alpha,+\\infty)</span>。","sourceNote":"已对照独立PDF整理卷核对题干；解析中的计算与推导已复核。","specialNote":"这里的范围按“保证对满足条件的函数都成立”理解；若只固定某个特殊函数（如常函数），能覆盖值域的区间也可能更短。","answerAlternatives":[]},{"id":"2022-shanghai-q13","paperId":"2022-shanghai","number":13,"type":"single","score":4,"lessonIds":["1.3"],"difficulty":"基础","hint":"把区间中所有整数列出来，注意右端2不在集合里。","legacy":false,"legacyReason":"","searchText":"若集合 A=[-1,2) ， B=\\Z ，则 A\\cap B= （ ） \\{-2,-1,0,1\\} \\{-1,0,1\\} \\{-1,0\\} \\{-1\\}","questionHtml":"若集合 <span class=\"gk-math\" data-tex=\"A=[-1,2)\">A=[-1,2)</span>，<span class=\"gk-math\" data-tex=\"B=\\Z\">B=\\Z</span>，则 <span class=\"gk-math\" data-tex=\"A\\cap B=\">A\\cap B=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\{-2,-1,0,1\\}\">\\{-2,-1,0,1\\}</span>","<span class=\"gk-math\" data-tex=\"\\{-1,0,1\\}\">\\{-1,0,1\\}</span>","<span class=\"gk-math\" data-tex=\"\\{-1,0\\}\">\\{-1,0\\}</span>","<span class=\"gk-math\" data-tex=\"\\{-1\\}\">\\{-1\\}</span>"],"answerHtml":"B","answerKey":"B","solutionHtml":"<span class=\"gk-math\" data-tex=\"A\\cap\\mathbb Z\">A\\cap\\mathbb Z</span>就是区间<span class=\"gk-math\" data-tex=\"[-1,2)\">[-1,2)</span>里的整数，依次为<span class=\"gk-math\" data-tex=\"-1,0,1\">-1,0,1</span>。注意右端点2不包含在内。故选B。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q14","paperId":"2022-shanghai","number":14,"type":"single","score":4,"lessonIds":["2.2"],"difficulty":"基础","hint":"用(a−b)²>0判断a+b与2√ab；再检查其余选项是否可能取等号。","legacy":false,"legacyReason":"","searchText":"若实数 a ， b 满足 a>b>0 ，则下列不等式中，恒成立的是（ ） a+b>2\\sqrt{ab} a+b<2\\sqrt{ab} \\frac a2+2b>2\\sqrt{ab} \\frac a2+2b<2\\sqrt{ab}","questionHtml":"若实数 <span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"b\">b</span> 满足 <span class=\"gk-math\" data-tex=\"a&gt;b&gt;0\">a&gt;b&gt;0</span>，则下列不等式中，恒成立的是（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"a+b&gt;2\\sqrt{ab}\">a+b&gt;2\\sqrt{ab}</span>","<span class=\"gk-math\" data-tex=\"a+b&lt;2\\sqrt{ab}\">a+b&lt;2\\sqrt{ab}</span>","<span class=\"gk-math\" data-tex=\"\\frac a2+2b&gt;2\\sqrt{ab}\">\\frac a2+2b&gt;2\\sqrt{ab}</span>","<span class=\"gk-math\" data-tex=\"\\frac a2+2b&lt;2\\sqrt{ab}\">\\frac a2+2b&lt;2\\sqrt{ab}</span>"],"answerHtml":"A","answerKey":"A","solutionHtml":"由<span class=\"gk-math\" data-tex=\"a&gt;b&gt;0\">a&gt;b&gt;0</span>得<span class=\"gk-math\" data-tex=\"a\\ne b\">a\\ne b</span>，所以基本不等式中等号不能成立，有<span class=\"gk-math\" data-tex=\"a+b&gt;2\\sqrt{ab}\">a+b&gt;2\\sqrt{ab}</span>，A恒成立。C有可能取等号，例如<span class=\"gk-math\" data-tex=\"a=4b\">a=4b</span>时<span class=\"gk-math\" data-tex=\"a/2+2b=2\\sqrt{ab}\">a/2+2b=2\\sqrt{ab}</span>，所以C不恒成立；B、D也不恒成立。故选A。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q15","paperId":"2022-shanghai","number":15,"type":"single","score":5,"lessonIds":["8.4","e1-1.3"],"difficulty":"挑战","hint":"把正方体放进坐标系，分别检查D₁到四个候选点的线段是否与两条遮挡线相交。","legacy":false,"legacyReason":"","searchText":"如图，在正方体 ABCD-A_1B_1C_1D_1 中， P ， Q ， R ， S 分别为棱 AB ， BC ， BB_1 ， CD 的中点，连接 A_1S ， B_1D . 对于空间任意两点 M ， N ，若线段 MN 上不存在也在线段 A_1S ， B_1D 上的点，则称 M ， N 两点“可视”，则下列选项中与点 D_1 “可视”的点为（ ） 点 P 点 B 点 R 点 Q","questionHtml":"如图，在正方体 <span class=\"gk-math\" data-tex=\"ABCD-A_1B_1C_1D_1\">ABCD-A_1B_1C_1D_1</span> 中，<span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span>，<span class=\"gk-math\" data-tex=\"R\">R</span>，<span class=\"gk-math\" data-tex=\"S\">S</span> 分别为棱 <span class=\"gk-math\" data-tex=\"AB\">AB</span>，<span class=\"gk-math\" data-tex=\"BC\">BC</span>，<span class=\"gk-math\" data-tex=\"BB_1\">BB_1</span>，<span class=\"gk-math\" data-tex=\"CD\">CD</span> 的中点，连接 <span class=\"gk-math\" data-tex=\"A_1S\">A_1S</span>，<span class=\"gk-math\" data-tex=\"B_1D\">B_1D</span>. 对于空间任意两点 <span class=\"gk-math\" data-tex=\"M\">M</span>，<span class=\"gk-math\" data-tex=\"N\">N</span>，若线段 <span class=\"gk-math\" data-tex=\"MN\">MN</span> 上不存在也在线段 <span class=\"gk-math\" data-tex=\"A_1S\">A_1S</span>，<span class=\"gk-math\" data-tex=\"B_1D\">B_1D</span> 上的点，则称 <span class=\"gk-math\" data-tex=\"M\">M</span>，<span class=\"gk-math\" data-tex=\"N\">N</span> 两点“可视”，则下列选项中与点 <span class=\"gk-math\" data-tex=\"D_1\">D_1</span>“可视”的点为（ ）<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,517px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/shanghai/q15_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/shanghai/q15_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"501\" height=\"487\" style=\"aspect-ratio:501/487;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":["点 <span class=\"gk-math\" data-tex=\"P\">P</span>","点 <span class=\"gk-math\" data-tex=\"B\">B</span>","点 <span class=\"gk-math\" data-tex=\"R\">R</span>","点 <span class=\"gk-math\" data-tex=\"Q\">Q</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"取<span class=\"gk-math\" data-tex=\"A(0,0,0)\">A(0,0,0)</span>、<span class=\"gk-math\" data-tex=\"B(1,0,0)\">B(1,0,0)</span>、<span class=\"gk-math\" data-tex=\"D(0,1,0)\">D(0,1,0)</span>、<span class=\"gk-math\" data-tex=\"A_1(0,0,1)\">A_1(0,0,1)</span>，则<span class=\"gk-math\" data-tex=\"D_1(0,1,1)\">D_1(0,1,1)</span>，<span class=\"gk-math\" data-tex=\"P(\\frac12,0,0)\">P(\\frac12,0,0)</span>，<span class=\"gk-math\" data-tex=\"Q(1,\\frac12,0)\">Q(1,\\frac12,0)</span>，<span class=\"gk-math\" data-tex=\"R(1,0,\\frac12)\">R(1,0,\\frac12)</span>，<span class=\"gk-math\" data-tex=\"S(\\frac12,1,0)\">S(\\frac12,1,0)</span>。线段<span class=\"gk-math\" data-tex=\"D_1P\">D_1P</span>在<span class=\"gk-math\" data-tex=\"(\\frac14,\\frac12,\\frac12)\">(\\frac14,\\frac12,\\frac12)</span>处与<span class=\"gk-math\" data-tex=\"A_1S\">A_1S</span>相交；<span class=\"gk-math\" data-tex=\"D_1B\">D_1B</span>在<span class=\"gk-math\" data-tex=\"(\\frac12,\\frac12,\\frac12)\">(\\frac12,\\frac12,\\frac12)</span>处与<span class=\"gk-math\" data-tex=\"B_1D\">B_1D</span>相交；<span class=\"gk-math\" data-tex=\"D_1R\">D_1R</span>在<span class=\"gk-math\" data-tex=\"(\\frac23,\\frac13,\\frac23)\">(\\frac23,\\frac13,\\frac23)</span>处与<span class=\"gk-math\" data-tex=\"B_1D\">B_1D</span>相交。对<span class=\"gk-math\" data-tex=\"D_1Q\">D_1Q</span>写参数式<span class=\"gk-math\" data-tex=\"(t,1-\\frac t2,1-t)\">(t,1-\\frac t2,1-t)</span>（<span class=\"gk-math\" data-tex=\"0\\le t\\le1\">0\\le t\\le1</span>），分别与<span class=\"gk-math\" data-tex=\"A_1S:(\\frac u2,u,1-u)\">A_1S:(\\frac u2,u,1-u)</span>和<span class=\"gk-math\" data-tex=\"B_1D:(1-v,v,1-v)\">B_1D:(1-v,v,1-v)</span>联立，均无解。因此只有Q可视，选D。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q16","paperId":"2022-shanghai","number":16,"type":"single","score":5,"lessonIds":["e1-2.4","e1-2.5"],"difficulty":"挑战","hint":"每个整数k对应一个圆：圆心是(k,k²)，半径是2√|k|。先试一条足够高的水平线。","legacy":false,"legacyReason":"","searchText":"设 \\Omega=\\{(x,y)\\mid (x-k)^2+(y-k^2)^2=4|k|,\\ k\\in\\Z\\} ，有结论： 存在直线 l ，使得 \\Omega 中不存在点在 l 上，但存在点在 l 两侧； 存在直线 l ，使得 \\Omega 中存在无数个点在 l 上. 关于以上两个结论，正确的判断是（ ） \\circled{1} 成立， \\circled{2} 成立 \\circled{1} 成立， \\circled{2} 不成立 \\circled{1} 不成立， \\circled{2} 成立 \\circled{1} 不成立， \\circled{2} 不成立","questionHtml":"设 <span class=\"gk-math\" data-tex=\"\\Omega=\\{(x,y)\\mid (x-k)^2+(y-k^2)^2=4|k|,\\ k\\in\\Z\\}\">\\Omega=\\{(x,y)\\mid (x-k)^2+(y-k^2)^2=4|k|,\\ k\\in\\Z\\}</span>，有结论： <ol class=\"gk-subparts\"><li>存在直线 <span class=\"gk-math\" data-tex=\"l\">l</span>，使得 <span class=\"gk-math\" data-tex=\"\\Omega\">\\Omega</span> 中不存在点在 <span class=\"gk-math\" data-tex=\"l\">l</span> 上，但存在点在 <span class=\"gk-math\" data-tex=\"l\">l</span> 两侧；</li><li>存在直线 <span class=\"gk-math\" data-tex=\"l\">l</span>，使得 <span class=\"gk-math\" data-tex=\"\\Omega\">\\Omega</span> 中存在无数个点在 <span class=\"gk-math\" data-tex=\"l\">l</span> 上.</li></ol> 关于以上两个结论，正确的判断是（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\circled{1}\">\\circled{1}</span>成立，<span class=\"gk-math\" data-tex=\"\\circled{2}\">\\circled{2}</span>成立","<span class=\"gk-math\" data-tex=\"\\circled{1}\">\\circled{1}</span>成立，<span class=\"gk-math\" data-tex=\"\\circled{2}\">\\circled{2}</span>不成立","<span class=\"gk-math\" data-tex=\"\\circled{1}\">\\circled{1}</span>不成立，<span class=\"gk-math\" data-tex=\"\\circled{2}\">\\circled{2}</span>成立","<span class=\"gk-math\" data-tex=\"\\circled{1}\">\\circled{1}</span>不成立，<span class=\"gk-math\" data-tex=\"\\circled{2}\">\\circled{2}</span>不成立"],"answerHtml":"B","answerKey":"B","solutionHtml":"把<span class=\"gk-math\" data-tex=\"\\Omega\">\\Omega</span>看成圆的集合：第k个圆的圆心是<span class=\"gk-math\" data-tex=\"(k,k^2)\">(k,k^2)</span>，半径为<span class=\"gk-math\" data-tex=\"2\\sqrt{|k|}\">2\\sqrt{|k|}</span>，k=0时退化成原点。对于<span class=\"gk-math\" data-tex=\"|k|\\le4\">|k|\\le4</span>，圆上点的纵坐标至多<span class=\"gk-math\" data-tex=\"16+4=20\">16+4=20</span>；对于<span class=\"gk-math\" data-tex=\"|k|\\ge5\">|k|\\ge5</span>，圆上点的纵坐标至少<span class=\"gk-math\" data-tex=\"25-2\\sqrt5&gt;20.5\">25-2\\sqrt5&gt;20.5</span>。所以直线<span class=\"gk-math\" data-tex=\"y=20.25\">y=20.25</span>不穿过任何一个圆，而圆在其上下两侧都有，结论①成立。对于任意一条直线，其到<span class=\"gk-math\" data-tex=\"(k,k^2)\">(k,k^2)</span>的距离当<span class=\"gk-math\" data-tex=\"|k|\">|k|</span>很大时最终大于<span class=\"gk-math\" data-tex=\"2\\sqrt{|k|}\">2\\sqrt{|k|}</span>：非竖直直线的分子含<span class=\"gk-math\" data-tex=\"k^2\">k^2</span>，竖直直线的距离含<span class=\"gk-math\" data-tex=\"|k|\">|k|</span>。因此每条直线只会与有限多个圆相交，每个圆至多贡献2个交点，结论②不成立。故选B。","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q17","paperId":"2022-shanghai","number":17,"type":"written","score":14,"lessonIds":["8.3","e1-1.4"],"difficulty":"进阶","hint":"先在直角三角形AOP中求高PO；线面角可用PM在平面PAC上的投影来求。","legacy":false,"legacyReason":"","searchText":"如图，已知三棱锥 P-ABC ，底面 ABC 为等边三角形， O 为 AC 的中点， AP=AC=2 ，且 PO\\perp 底面 ABC . 求三棱锥 P-ABC 的体积 V ； 若 M 为 BC 中点，求 PM 与平面 PAC 所成角的大小. ","questionHtml":"如图，已知三棱锥 <span class=\"gk-math\" data-tex=\"P-ABC\">P-ABC</span>，底面 <span class=\"gk-math\" data-tex=\"ABC\">ABC</span> 为等边三角形，<span class=\"gk-math\" data-tex=\"O\">O</span> 为 <span class=\"gk-math\" data-tex=\"AC\">AC</span> 的中点，<span class=\"gk-math\" data-tex=\"AP=AC=2\">AP=AC=2</span>，且 <span class=\"gk-math\" data-tex=\"PO\\perp\">PO\\perp</span> 底面 <span class=\"gk-math\" data-tex=\"ABC\">ABC</span>. <ol class=\"gk-subparts\"><li>求三棱锥 <span class=\"gk-math\" data-tex=\"P-ABC\">P-ABC</span> 的体积 <span class=\"gk-math\" data-tex=\"V\">V</span>；</li><li>若 <span class=\"gk-math\" data-tex=\"M\">M</span> 为 <span class=\"gk-math\" data-tex=\"BC\">BC</span> 中点，求 <span class=\"gk-math\" data-tex=\"PM\">PM</span> 与平面 <span class=\"gk-math\" data-tex=\"PAC\">PAC</span> 所成角的大小.</li></ol><br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,487px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/shanghai/q17_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/shanghai/q17_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"471\" height=\"551\" style=\"aspect-ratio:471/551;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由 <span class=\"gk-math\" data-tex=\"O\">O</span> 为 <span class=\"gk-math\" data-tex=\"AC\">AC</span> 的中点，得 <span class=\"gk-math\" data-tex=\"AO=1\">AO=1</span>. 又因为 <span class=\"gk-math\" data-tex=\"PO\\perp\">PO\\perp</span> 底面 <span class=\"gk-math\" data-tex=\"ABC\">ABC</span>，所以 <span class=\"gk-math\" data-tex=\"PO\\perp AO\">PO\\perp AO</span>. 在直角三角形 <span class=\"gk-math\" data-tex=\"AOP\">AOP</span> 中， <div class=\"gk-math display\" data-tex=\"PO=\\sqrt{AP^2-AO^2}=\\sqrt{2^2-1^2}=\\sqrt3\">PO=\\sqrt{AP^2-AO^2}=\\sqrt{2^2-1^2}=\\sqrt3</div> 底面 <span class=\"gk-math\" data-tex=\"ABC\">ABC</span> 是边长为 <span class=\"gk-math\" data-tex=\"2\">2</span> 的等边三角形，所以 <div class=\"gk-math display\" data-tex=\"S_{\\triangle ABC}=\\frac{\\sqrt3}{4}\\times2^2=\\sqrt3\">S_{\\triangle ABC}=\\frac{\\sqrt3}{4}\\times2^2=\\sqrt3</div> 因此三棱锥的体积为 <div class=\"gk-math display\" data-tex=\"V=\\frac13S_{\\triangle ABC}\\cdot PO=\\frac13\\times\\sqrt3\\times\\sqrt3=1\">V=\\frac13S_{\\triangle ABC}\\cdot PO=\\frac13\\times\\sqrt3\\times\\sqrt3=1</div></li><li>以 <span class=\"gk-math\" data-tex=\"O\">O</span> 为原点，<span class=\"gk-math\" data-tex=\"AC\">AC</span> 所在直线为 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴，<span class=\"gk-math\" data-tex=\"PO\">PO</span> 所在直线为 <span class=\"gk-math\" data-tex=\"z\">z</span> 轴建立空间直角坐标系，并取 <span class=\"gk-math\" data-tex=\"B\">B</span> 在 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴正半轴上，则 <span class=\"gk-math\" data-tex=\"A(-1,0,0)\">A(-1,0,0)</span>，<span class=\"gk-math\" data-tex=\"C(1,0,0)\">C(1,0,0)</span>，<span class=\"gk-math\" data-tex=\"B(0,\\sqrt3,0)\">B(0,\\sqrt3,0)</span>，<span class=\"gk-math\" data-tex=\"P(0,0,\\sqrt3)\">P(0,0,\\sqrt3)</span>. 由于 <span class=\"gk-math\" data-tex=\"M\">M</span> 为 <span class=\"gk-math\" data-tex=\"BC\">BC</span> 的中点，得 <span class=\"gk-math\" data-tex=\"M\\left(\\frac12,\\frac{\\sqrt3}{2},0\\right)\">M\\left(\\frac12,\\frac{\\sqrt3}{2},0\\right)</span>. 平面 <span class=\"gk-math\" data-tex=\"PAC\">PAC</span> 的方程为 <span class=\"gk-math\" data-tex=\"y=0\">y=0</span>，且 <span class=\"gk-math\" data-tex=\"\\overrightarrow{PM}=\\left(\\frac12,\\frac{\\sqrt3}{2},-\\sqrt3\\right)\">\\overrightarrow{PM}=\\left(\\frac12,\\frac{\\sqrt3}{2},-\\sqrt3\\right)</span>，<span class=\"gk-math\" data-tex=\"PM=\\sqrt{\\frac14+\\frac34+3}=2\">PM=\\sqrt{\\frac14+\\frac34+3}=2</span>. 设 <span class=\"gk-math\" data-tex=\"PM\">PM</span> 与平面 <span class=\"gk-math\" data-tex=\"PAC\">PAC</span> 所成的角为 <span class=\"gk-math\" data-tex=\"\\alpha\">\\alpha</span>，则 <div class=\"gk-math display\" data-tex=\"\\sin\\alpha=\\frac{\\left|\\frac{\\sqrt3}{2}\\right|}{PM}=\\frac{\\sqrt3}{4}\">\\sin\\alpha=\\frac{\\left|\\frac{\\sqrt3}{2}\\right|}{PM}=\\frac{\\sqrt3}{4}</div> 所以 <span class=\"gk-math\" data-tex=\"\\alpha=\\arcsin\\frac{\\sqrt3}{4}\">\\alpha=\\arcsin\\frac{\\sqrt3}{4}</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q18","paperId":"2022-shanghai","number":18,"type":"written","score":14,"lessonIds":["4.3","4.4","2.3"],"difficulty":"进阶","hint":"第一问先写f(3)=f(5)；第二问先保证两个对数式都有意义。","legacy":false,"legacyReason":"","searchText":"设 a 为常数， f(x)=\\log_3(a+x)+\\log_3(6-x) . 若将函数 y=f(x) 的图像向下平移 m （ m>0 ）个单位后，其图像经过 (3,0) ， (5,0) 两点，求实数 a 和 m 的值； 若 a>-3 且 a\\ne0 ，解不等式 f(x)\\le f(6-x) . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"a\">a</span> 为常数，<span class=\"gk-math\" data-tex=\"f(x)=\\log_3(a+x)+\\log_3(6-x)\">f(x)=\\log_3(a+x)+\\log_3(6-x)</span>. <ol class=\"gk-subparts\"><li>若将函数 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 的图像向下平移 <span class=\"gk-math\" data-tex=\"m\">m</span>（<span class=\"gk-math\" data-tex=\"m&gt;0\">m&gt;0</span>）个单位后，其图像经过 <span class=\"gk-math\" data-tex=\"(3,0)\">(3,0)</span>，<span class=\"gk-math\" data-tex=\"(5,0)\">(5,0)</span> 两点，求实数 <span class=\"gk-math\" data-tex=\"a\">a</span> 和 <span class=\"gk-math\" data-tex=\"m\">m</span> 的值；</li><li>若 <span class=\"gk-math\" data-tex=\"a&gt;-3\">a&gt;-3</span> 且 <span class=\"gk-math\" data-tex=\"a\\ne0\">a\\ne0</span>，解不等式 <span class=\"gk-math\" data-tex=\"f(x)\\le f(6-x)\">f(x)\\le f(6-x)</span>.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>函数图像向下平移 <span class=\"gk-math\" data-tex=\"m\">m</span> 个单位后为 <span class=\"gk-math\" data-tex=\"y=f(x)-m\">y=f(x)-m</span>. 该图像经过 <span class=\"gk-math\" data-tex=\"(3,0)\">(3,0)</span>，<span class=\"gk-math\" data-tex=\"(5,0)\">(5,0)</span>，所以 <span class=\"gk-math\" data-tex=\"f(3)=f(5)=m\">f(3)=f(5)=m</span>. 由定义域可知 <span class=\"gk-math\" data-tex=\"a&gt;-3\">a&gt;-3</span>. 又 <span class=\"gk-math\" data-tex=\"f(3)=\\log_3\\bigl(3(a+3)\\bigr)\">f(3)=\\log_3\\bigl(3(a+3)\\bigr)</span>，<span class=\"gk-math\" data-tex=\"f(5)=\\log_3(a+5)\">f(5)=\\log_3(a+5)</span>. 由 <span class=\"gk-math\" data-tex=\"f(3)=f(5)\">f(3)=f(5)</span> 和对数函数的单调性，得 <div class=\"gk-math display\" data-tex=\"3(a+3)=a+5\">3(a+3)=a+5</div> 解得 <span class=\"gk-math\" data-tex=\"a=-2\">a=-2</span>. 于是 <div class=\"gk-math display\" data-tex=\"m=f(5)=\\log_3(3)=1\">m=f(5)=\\log_3(3)=1</div></li><li>要使 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 与 <span class=\"gk-math\" data-tex=\"f(6-x)\">f(6-x)</span> 同时有意义，需要 <span class=\"gk-math\" data-tex=\"a+x&gt;0\">a+x&gt;0</span>，<span class=\"gk-math\" data-tex=\"6-x&gt;0\">6-x&gt;0</span>，<span class=\"gk-math\" data-tex=\"a+6-x&gt;0\">a+6-x&gt;0</span>，<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>. 因此 <div class=\"gk-math display\" data-tex=\"x\\in\\bigl(\\max\\{-a,0\\},\\min\\{6,a+6\\}\\bigr)\">x\\in\\bigl(\\max\\{-a,0\\},\\min\\{6,a+6\\}\\bigr)</div> 在这个公共定义域内，由于底数 <span class=\"gk-math\" data-tex=\"3&gt;1\">3&gt;1</span>， <div class=\"gk-math display\" data-tex=\"f(x)\\le f(6-x)\\Longleftrightarrow (a+x)(6-x)\\le x(a+6-x)\\Longleftrightarrow 6a\\le2ax\">f(x)\\le f(6-x)\\Longleftrightarrow (a+x)(6-x)\\le x(a+6-x)\\Longleftrightarrow 6a\\le2ax</div> 当 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span> 时，公共定义域为 <span class=\"gk-math\" data-tex=\"(0,6)\">(0,6)</span>，不等式等价于 <span class=\"gk-math\" data-tex=\"x\\ge3\">x\\ge3</span>，故解集为 <span class=\"gk-math\" data-tex=\"[3,6)\">[3,6)</span>.<br><br>当 <span class=\"gk-math\" data-tex=\"-3&lt;a&lt;0\">-3&lt;a&lt;0</span> 时，公共定义域为 <span class=\"gk-math\" data-tex=\"(-a,a+6)\">(-a,a+6)</span>，并且 <span class=\"gk-math\" data-tex=\"-a&lt;3&lt;a+6\">-a&lt;3&lt;a+6</span>. 不等式等价于 <span class=\"gk-math\" data-tex=\"x\\le3\">x\\le3</span>，故解集为 <span class=\"gk-math\" data-tex=\"(-a,3]\">(-a,3]</span>.<br><br>综上，原不等式的解集为 <div class=\"gk-math display\" data-tex=\"\\begin{cases}\n(-a,3],&amp;-3&lt;a&lt;0,\\\\\n[3,6),&amp;a&gt;0.\n\\end{cases}\">\\begin{cases}\n(-a,3],&amp;-3&lt;a&lt;0,\\\\\n[3,6),&amp;a&gt;0.\n\\end{cases}</div></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q19","paperId":"2022-shanghai","number":19,"type":"written","score":14,"lessonIds":["6.4","5.7","e2-5.3"],"difficulty":"挑战","hint":"把O设为原点，先求圆弧半径；利用P、Q对称，把五边形面积写成一个角的函数。","legacy":false,"legacyReason":"","searchText":"如图， AD=BC=6 ， AB=20 ， \\angle DAB=\\angle ABC=120^\\circ ， O 为 AB 中点，曲线 CD 上任意一点到点 O 的距离均相等， P ， M ， Q 为曲线 CD 上的点，且 MO\\perp AB ，点 P 与点 Q 关于直线 OM 对称. 若点 P 与点 C 重合，求 \\angle POB 的大小； 点 P 在何位置时，五边形 CPMQD 的面积 S 取到最大值，并求出该最大值. ","questionHtml":"如图，<span class=\"gk-math\" data-tex=\"AD=BC=6\">AD=BC=6</span>，<span class=\"gk-math\" data-tex=\"AB=20\">AB=20</span>，<span class=\"gk-math\" data-tex=\"\\angle DAB=\\angle ABC=120^\\circ\">\\angle DAB=\\angle ABC=120^\\circ</span>，<span class=\"gk-math\" data-tex=\"O\">O</span> 为 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 中点，曲线 <span class=\"gk-math\" data-tex=\"CD\">CD</span> 上任意一点到点 <span class=\"gk-math\" data-tex=\"O\">O</span> 的距离均相等，<span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"M\">M</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span> 为曲线 <span class=\"gk-math\" data-tex=\"CD\">CD</span> 上的点，且 <span class=\"gk-math\" data-tex=\"MO\\perp AB\">MO\\perp AB</span>，点 <span class=\"gk-math\" data-tex=\"P\">P</span> 与点 <span class=\"gk-math\" data-tex=\"Q\">Q</span> 关于直线 <span class=\"gk-math\" data-tex=\"OM\">OM</span> 对称. <ol class=\"gk-subparts\"><li>若点 <span class=\"gk-math\" data-tex=\"P\">P</span> 与点 <span class=\"gk-math\" data-tex=\"C\">C</span> 重合，求 <span class=\"gk-math\" data-tex=\"\\angle POB\">\\angle POB</span> 的大小；</li><li>点 <span class=\"gk-math\" data-tex=\"P\">P</span> 在何位置时，五边形 <span class=\"gk-math\" data-tex=\"CPMQD\">CPMQD</span> 的面积 <span class=\"gk-math\" data-tex=\"S\">S</span> 取到最大值，并求出该最大值.</li></ol><br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,743px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/shanghai/q19_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/shanghai/q19_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"727\" height=\"439\" style=\"aspect-ratio:727/439;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>以 <span class=\"gk-math\" data-tex=\"O\">O</span> 为原点，<span class=\"gk-math\" data-tex=\"AB\">AB</span> 所在直线为 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴建立平面直角坐标系，取 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴正方向指向曲线 <span class=\"gk-math\" data-tex=\"CD\">CD</span> 一侧，则 <span class=\"gk-math\" data-tex=\"A(-10,0)\">A(-10,0)</span>，<span class=\"gk-math\" data-tex=\"B(10,0)\">B(10,0)</span>. 由 <span class=\"gk-math\" data-tex=\"AD=6\">AD=6</span> 及 <span class=\"gk-math\" data-tex=\"\\angle DAB=120^\\circ\">\\angle DAB=120^\\circ</span>，得 <div class=\"gk-math display\" data-tex=\"D\\bigl(-10+6\\cos120^\\circ,6\\sin120^\\circ\\bigr)=(-13,3\\sqrt3)\">D\\bigl(-10+6\\cos120^\\circ,6\\sin120^\\circ\\bigr)=(-13,3\\sqrt3)</div> 同理，由 <span class=\"gk-math\" data-tex=\"BC=6\">BC=6</span> 及 <span class=\"gk-math\" data-tex=\"\\angle ABC=120^\\circ\">\\angle ABC=120^\\circ</span>，得 <span class=\"gk-math\" data-tex=\"C=(13,3\\sqrt3)\">C=(13,3\\sqrt3)</span>. 因而 <div class=\"gk-math display\" data-tex=\"OD=OC=\\sqrt{13^2+(3\\sqrt3)^2}=14\">OD=OC=\\sqrt{13^2+(3\\sqrt3)^2}=14</div> 若 <span class=\"gk-math\" data-tex=\"P\">P</span> 与 <span class=\"gk-math\" data-tex=\"C\">C</span> 重合，则 <span class=\"gk-math\" data-tex=\"P=(13,3\\sqrt3)\">P=(13,3\\sqrt3)</span>，所以 <div class=\"gk-math display\" data-tex=\"\\cos\\angle POB=\\frac{\\overrightarrow{OP}\\cdot\\overrightarrow{OB}}{OP\\cdot OB}=\\frac{13\\times10}{14\\times10}=\\frac{13}{14}\">\\cos\\angle POB=\\frac{\\overrightarrow{OP}\\cdot\\overrightarrow{OB}}{OP\\cdot OB}=\\frac{13\\times10}{14\\times10}=\\frac{13}{14}</div> 故 <span class=\"gk-math\" data-tex=\"\\angle POB=\\arccos\\frac{13}{14}\">\\angle POB=\\arccos\\frac{13}{14}</span>.</li><li>由 <span class=\"gk-math\" data-tex=\"MO\\perp AB\">MO\\perp AB</span> 及 <span class=\"gk-math\" data-tex=\"OM=14\">OM=14</span>，得 <span class=\"gk-math\" data-tex=\"M=(0,14)\">M=(0,14)</span>. 设 <span class=\"gk-math\" data-tex=\"h=3\\sqrt3\">h=3\\sqrt3</span>，<span class=\"gk-math\" data-tex=\"P=(x,y)\">P=(x,y)</span>，<span class=\"gk-math\" data-tex=\"Q=(-x,y)\">Q=(-x,y)</span>，<span class=\"gk-math\" data-tex=\"y=\\sqrt{196-x^2}\">y=\\sqrt{196-x^2}</span> 其中 <span class=\"gk-math\" data-tex=\"0\\le x\\le13\">0\\le x\\le13</span>. 按顶点 <span class=\"gk-math\" data-tex=\"C\">C</span>，<span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"M\">M</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span>，<span class=\"gk-math\" data-tex=\"D\">D</span> 的顺序计算五边形面积，得 <div class=\"gk-math display\" data-tex=\"S=13(y-h)+(14-h)x=13\\sqrt{196-x^2}+(14-h)x-13h\">S=13(y-h)+(14-h)x=13\\sqrt{196-x^2}+(14-h)x-13h</div> 令 <span class=\"gk-math\" data-tex=\"k=14-h=14-3\\sqrt3\">k=14-h=14-3\\sqrt3</span>. 因为 <span class=\"gk-math\" data-tex=\"x^2+y^2=196\">x^2+y^2=196</span>，由柯西不等式， <div class=\"gk-math display\" data-tex=\"13y+kx\\le14\\sqrt{13^2+k^2}\">13y+kx\\le14\\sqrt{13^2+k^2}</div> 当且仅当 <span class=\"gk-math\" data-tex=\"(x,y)\">(x,y)</span> 与 <span class=\"gk-math\" data-tex=\"(k,13)\">(k,13)</span> 同方向时取等号. 注意到 <div class=\"gk-math display\" data-tex=\"13^2+k^2=169+(14-3\\sqrt3)^2=28(14-3\\sqrt3)=28k\">13^2+k^2=169+(14-3\\sqrt3)^2=28(14-3\\sqrt3)=28k</div> 所以取最大值时 <span class=\"gk-math\" data-tex=\"x^2=\\frac{14^2k^2}{13^2+k^2}=7k=98-21\\sqrt3\">x^2=\\frac{14^2k^2}{13^2+k^2}=7k=98-21\\sqrt3</span>，<span class=\"gk-math\" data-tex=\"y^2=196-x^2=98+21\\sqrt3\">y^2=196-x^2=98+21\\sqrt3</span>. 即点 <span class=\"gk-math\" data-tex=\"P\">P</span> 在所建坐标系中的位置为 <div class=\"gk-math display\" data-tex=\"P\\left(\\sqrt{98-21\\sqrt3},\\sqrt{98+21\\sqrt3}\\right)\">P\\left(\\sqrt{98-21\\sqrt3},\\sqrt{98+21\\sqrt3}\\right)</div> 点 <span class=\"gk-math\" data-tex=\"Q\">Q</span> 为其关于 <span class=\"gk-math\" data-tex=\"OM\">OM</span> 的对称点. 此时 <div class=\"gk-math display\" data-tex=\"S_{\\max}=14\\sqrt{169+k^2}-13h=14\\sqrt{28(14-3\\sqrt3)}-39\\sqrt3=28\\sqrt{98-21\\sqrt3}-39\\sqrt3\">S_{\\max}=14\\sqrt{169+k^2}-13h=14\\sqrt{28(14-3\\sqrt3)}-39\\sqrt3=28\\sqrt{98-21\\sqrt3}-39\\sqrt3</div></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q20","paperId":"2022-shanghai","number":20,"type":"written","score":18,"lessonIds":["e1-3.1","e1-2.3","6.4"],"difficulty":"挑战","hint":"先用c²=a²−b²；最后一问把两段焦距之和直接换成2a。","legacy":false,"legacyReason":"","searchText":"设椭圆 \\Gamma:\\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1 （ a>b>0 ）， F_1(-\\sqrt2,0) ， F_2(\\sqrt2,0) 为 \\Gamma 的焦点， A 为 \\Gamma 的下顶点， M 为直线 l:x+y-4\\sqrt2=0 上一点. 若 a=2 ，且 AM 的中点在 x 轴上，求点 M 的坐标； 若直线 l 与 y 轴的交点为 B ，直线 AM 经过点 F_2 ，且在 \\triangle ABM 中有一内角的余弦值为 \\frac35 ，求 b 的值； 若 \\Gamma 上一点 P 到 l 的距离为 d ，且 |PF_1|+|PF_2|+d=6 ，求 d 的最小值. ","questionHtml":"设椭圆 <span class=\"gk-math\" data-tex=\"\\Gamma:\\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1\">\\Gamma:\\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;b&gt;0\">a&gt;b&gt;0</span>），<span class=\"gk-math\" data-tex=\"F_1(-\\sqrt2,0)\">F_1(-\\sqrt2,0)</span>，<span class=\"gk-math\" data-tex=\"F_2(\\sqrt2,0)\">F_2(\\sqrt2,0)</span> 为 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 的焦点，<span class=\"gk-math\" data-tex=\"A\">A</span> 为 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 的下顶点，<span class=\"gk-math\" data-tex=\"M\">M</span> 为直线 <span class=\"gk-math\" data-tex=\"l:x+y-4\\sqrt2=0\">l:x+y-4\\sqrt2=0</span> 上一点. <ol class=\"gk-subparts\"><li>若 <span class=\"gk-math\" data-tex=\"a=2\">a=2</span>，且 <span class=\"gk-math\" data-tex=\"AM\">AM</span> 的中点在 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴上，求点 <span class=\"gk-math\" data-tex=\"M\">M</span> 的坐标；</li><li>若直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 与 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴的交点为 <span class=\"gk-math\" data-tex=\"B\">B</span>，直线 <span class=\"gk-math\" data-tex=\"AM\">AM</span> 经过点 <span class=\"gk-math\" data-tex=\"F_2\">F_2</span>，且在 <span class=\"gk-math\" data-tex=\"\\triangle ABM\">\\triangle ABM</span> 中有一内角的余弦值为 <span class=\"gk-math\" data-tex=\"\\frac35\">\\frac35</span>，求 <span class=\"gk-math\" data-tex=\"b\">b</span> 的值；</li><li>若 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 上一点 <span class=\"gk-math\" data-tex=\"P\">P</span> 到 <span class=\"gk-math\" data-tex=\"l\">l</span> 的距离为 <span class=\"gk-math\" data-tex=\"d\">d</span>，且 <span class=\"gk-math\" data-tex=\"|PF_1|+|PF_2|+d=6\">|PF_1|+|PF_2|+d=6</span>，求 <span class=\"gk-math\" data-tex=\"d\">d</span> 的最小值.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由焦点坐标可知椭圆的半焦距为 <span class=\"gk-math\" data-tex=\"c=\\sqrt2\">c=\\sqrt2</span>，所以 <span class=\"gk-math\" data-tex=\"a^2-b^2=c^2=2\">a^2-b^2=c^2=2</span>. 当 <span class=\"gk-math\" data-tex=\"a=2\">a=2</span> 时，<span class=\"gk-math\" data-tex=\"b=\\sqrt2\">b=\\sqrt2</span>，从而 <span class=\"gk-math\" data-tex=\"A=(0,-\\sqrt2)\">A=(0,-\\sqrt2)</span>. 设 <span class=\"gk-math\" data-tex=\"M=(x_M,y_M)\">M=(x_M,y_M)</span>，由 <span class=\"gk-math\" data-tex=\"AM\">AM</span> 的中点在 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴上，得 <span class=\"gk-math\" data-tex=\"\\frac{-\\sqrt2+y_M}{2}=0\">\\frac{-\\sqrt2+y_M}{2}=0</span>，<span class=\"gk-math\" data-tex=\"y_M=\\sqrt2\">y_M=\\sqrt2</span>. 又 <span class=\"gk-math\" data-tex=\"M\\in l\">M\\in l</span>，所以 <span class=\"gk-math\" data-tex=\"x_M+\\sqrt2=4\\sqrt2\">x_M+\\sqrt2=4\\sqrt2</span>，<span class=\"gk-math\" data-tex=\"x_M=3\\sqrt2\">x_M=3\\sqrt2</span>. 故 <span class=\"gk-math\" data-tex=\"M=(3\\sqrt2,\\sqrt2)\">M=(3\\sqrt2,\\sqrt2)</span>.</li><li>直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 与 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴的交点为 <span class=\"gk-math\" data-tex=\"B=(0,4\\sqrt2)\">B=(0,4\\sqrt2)</span>. 令 <div class=\"gk-math display\" data-tex=\"t=\\frac{b}{\\sqrt2}&gt;0\">t=\\frac{b}{\\sqrt2}&gt;0</div> 由于 <span class=\"gk-math\" data-tex=\"A=(0,-b)\">A=(0,-b)</span>，且直线 <span class=\"gk-math\" data-tex=\"AM\">AM</span> 经过 <span class=\"gk-math\" data-tex=\"F_2=(\\sqrt2,0)\">F_2=(\\sqrt2,0)</span>，直线 <span class=\"gk-math\" data-tex=\"AM\">AM</span> 的方程为 <div class=\"gk-math display\" data-tex=\"y=tx-\\sqrt2t\">y=tx-\\sqrt2t</div> 联立 <span class=\"gk-math\" data-tex=\"x+y=4\\sqrt2\">x+y=4\\sqrt2</span>，得 <div class=\"gk-math display\" data-tex=\"M\\left(\\frac{\\sqrt2(4+t)}{1+t},\\frac{3\\sqrt2t}{1+t}\\right)\">M\\left(\\frac{\\sqrt2(4+t)}{1+t},\\frac{3\\sqrt2t}{1+t}\\right)</div> 直接由向量夹角公式，三角形 <span class=\"gk-math\" data-tex=\"ABM\">ABM</span> 的三个内角满足 <span class=\"gk-math\" data-tex=\"\\cos\\angle BAM=\\frac{t}{\\sqrt{1+t^2}}\">\\cos\\angle BAM=\\frac{t}{\\sqrt{1+t^2}}</span>，<span class=\"gk-math\" data-tex=\"\\cos\\angle ABM=\\frac1{\\sqrt2}\">\\cos\\angle ABM=\\frac1{\\sqrt2}</span>，<span class=\"gk-math\" data-tex=\"\\cos\\angle AMB=\\frac{1-t}{\\sqrt{2(1+t^2)}}\">\\cos\\angle AMB=\\frac{1-t}{\\sqrt{2(1+t^2)}}</span>. 其中 <span class=\"gk-math\" data-tex=\"\\cos\\angle ABM\\ne\\frac35\">\\cos\\angle ABM\\ne\\frac35</span>. 若 <span class=\"gk-math\" data-tex=\"\\cos\\angle BAM=\\frac35\">\\cos\\angle BAM=\\frac35</span>，则 <span class=\"gk-math\" data-tex=\"\\frac{t}{\\sqrt{1+t^2}}=\\frac35\">\\frac{t}{\\sqrt{1+t^2}}=\\frac35</span>，<span class=\"gk-math\" data-tex=\"t=\\frac34\">t=\\frac34</span>，<span class=\"gk-math\" data-tex=\"b=\\frac{3\\sqrt2}{4}\">b=\\frac{3\\sqrt2}{4}</span>. 若 <span class=\"gk-math\" data-tex=\"\\cos\\angle AMB=\\frac35\">\\cos\\angle AMB=\\frac35</span>，则因右端为正数，先得 <span class=\"gk-math\" data-tex=\"t&lt;1\">t&lt;1</span>. 再平方得 <span class=\"gk-math\" data-tex=\"25(1-t)^2=18(1+t^2)\">25(1-t)^2=18(1+t^2)</span>，<span class=\"gk-math\" data-tex=\"7t^2-50t+7=0\">7t^2-50t+7=0</span>. 所以 <span class=\"gk-math\" data-tex=\"t=7\">t=7</span> 或 <span class=\"gk-math\" data-tex=\"t=\\frac17\">t=\\frac17</span>，结合 <span class=\"gk-math\" data-tex=\"t&lt;1\">t&lt;1</span> 得 <span class=\"gk-math\" data-tex=\"t=\\frac17\">t=\\frac17</span>，从而 <span class=\"gk-math\" data-tex=\"b=\\frac{\\sqrt2}{7}\">b=\\frac{\\sqrt2}{7}</span>. 综上， <div class=\"gk-math display\" data-tex=\"b=\\frac{3\\sqrt2}{4}\\quad\\text{或}\\quad b=\\frac{\\sqrt2}{7}\">b=\\frac{3\\sqrt2}{4}\\quad\\text{或}\\quad b=\\frac{\\sqrt2}{7}</div></li><li>椭圆的焦半距为 <span class=\"gk-math\" data-tex=\"\\sqrt2\">\\sqrt2</span>，故椭圆上任意点 <span class=\"gk-math\" data-tex=\"P\">P</span> 都满足 <div class=\"gk-math display\" data-tex=\"|PF_1|+|PF_2|=2a\">|PF_1|+|PF_2|=2a</div> 由 <span class=\"gk-math\" data-tex=\"d\\ge0\">d\\ge0</span> 及题设，得 <span class=\"gk-math\" data-tex=\"a\\le3\">a\\le3</span>. 又 <span class=\"gk-math\" data-tex=\"b^2=a^2-2\">b^2=a^2-2</span>，所以当 <span class=\"gk-math\" data-tex=\"a\\le3\">a\\le3</span> 时，椭圆上任意点均满足 <div class=\"gk-math display\" data-tex=\"x+y\\le\\sqrt{a^2+b^2}=\\sqrt{2a^2-2}\\le4&lt;4\\sqrt2\">x+y\\le\\sqrt{a^2+b^2}=\\sqrt{2a^2-2}\\le4&lt;4\\sqrt2</div> 因此点 <span class=\"gk-math\" data-tex=\"P\">P</span> 在线 <span class=\"gk-math\" data-tex=\"l\">l</span> 的下方，且 <div class=\"gk-math display\" data-tex=\"d=\\frac{4\\sqrt2-x-y}{\\sqrt2}=4-\\frac{x+y}{\\sqrt2}\">d=\\frac{4\\sqrt2-x-y}{\\sqrt2}=4-\\frac{x+y}{\\sqrt2}</div> 设 <span class=\"gk-math\" data-tex=\"P=(a\\cos\\theta,b\\sin\\theta)\">P=(a\\cos\\theta,b\\sin\\theta)</span>，由题设得 <div class=\"gk-math display\" data-tex=\"2a+4-\\frac{a\\cos\\theta+b\\sin\\theta}{\\sqrt2}=6\">2a+4-\\frac{a\\cos\\theta+b\\sin\\theta}{\\sqrt2}=6</div> 即 <div class=\"gk-math display\" data-tex=\"a\\cos\\theta+b\\sin\\theta=2\\sqrt2(a-1)\">a\\cos\\theta+b\\sin\\theta=2\\sqrt2(a-1)</div> 由柯西不等式，必须有 <div class=\"gk-math display\" data-tex=\"2\\sqrt2(a-1)\\le\\sqrt{a^2+b^2}=\\sqrt{2a^2-2}\">2\\sqrt2(a-1)\\le\\sqrt{a^2+b^2}=\\sqrt{2a^2-2}</div> 由于 <span class=\"gk-math\" data-tex=\"a&gt;\\sqrt2\">a&gt;\\sqrt2</span>，两边非负，平方并整理得 <span class=\"gk-math\" data-tex=\"4(a-1)^2\\le a^2-1\">4(a-1)^2\\le a^2-1</span>，<span class=\"gk-math\" data-tex=\"(3a-5)(a-1)\\le0\">(3a-5)(a-1)\\le0</span>， 从而 <span class=\"gk-math\" data-tex=\"a\\le\\frac53\">a\\le\\frac53</span>. 于是 <div class=\"gk-math display\" data-tex=\"d=6-2a\\ge6-2\\times\\frac53=\\frac83\">d=6-2a\\ge6-2\\times\\frac53=\\frac83</div> 当 <span class=\"gk-math\" data-tex=\"a=\\frac53\">a=\\frac53</span>，<span class=\"gk-math\" data-tex=\"b=\\frac{\\sqrt7}{3}\">b=\\frac{\\sqrt7}{3}</span>，并取 <span class=\"gk-math\" data-tex=\"(\\cos\\theta,\\sin\\theta)\">(\\cos\\theta,\\sin\\theta)</span> 与 <span class=\"gk-math\" data-tex=\"(a,b)\">(a,b)</span> 同方向时，柯西不等式取等号，题设条件可以实现. 因此 <div class=\"gk-math display\" data-tex=\"d_{\\min}=\\frac83\">d_{\\min}=\\frac83</div></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-shanghai-q21","paperId":"2022-shanghai","number":21,"type":"written","score":18,"lessonIds":["e2-4.1","e2-4.2","e2-4.4"],"difficulty":"挑战","hint":"先按递推条件列出a₃和a₄的可能值，再利用前面各项严格递增约束后面的选择。","legacy":false,"legacyReason":"","searchText":"在数列 \\{a_n\\} 中， a_1=1 ， a_2=3 ，对任意 n\\in\\N^* 且 n\\ge2 ，均存在正整数 i\\in[1,n-1] ，满足 a_{n+1}=2a_n-a_i . 求 a_4 所有可能的值； 命题 p ：若 a_1 ， a_2 ，…， a_8 成等差数列，则 a_9<30 ，证明 p 是真命题，同时写出 p 的逆命题 q ，并判断命题 q 是真命题还是假命题，说明理由； 若 a_{2m}=3^m （ m\\in\\N^* ），求数列 \\{a_n\\} 的通项公式. ","questionHtml":"在数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 中，<span class=\"gk-math\" data-tex=\"a_1=1\">a_1=1</span>，<span class=\"gk-math\" data-tex=\"a_2=3\">a_2=3</span>，对任意 <span class=\"gk-math\" data-tex=\"n\\in\\N^*\">n\\in\\N^*</span> 且 <span class=\"gk-math\" data-tex=\"n\\ge2\">n\\ge2</span>，均存在正整数 <span class=\"gk-math\" data-tex=\"i\\in[1,n-1]\">i\\in[1,n-1]</span>，满足 <span class=\"gk-math\" data-tex=\"a_{n+1}=2a_n-a_i\">a_{n+1}=2a_n-a_i</span>. <ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"a_4\">a_4</span> 所有可能的值；</li><li>命题 <span class=\"gk-math\" data-tex=\"p\">p</span>：若 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"a_2\">a_2</span>，…，<span class=\"gk-math\" data-tex=\"a_8\">a_8</span> 成等差数列，则 <span class=\"gk-math\" data-tex=\"a_9&lt;30\">a_9&lt;30</span>，证明 <span class=\"gk-math\" data-tex=\"p\">p</span> 是真命题，同时写出 <span class=\"gk-math\" data-tex=\"p\">p</span> 的逆命题 <span class=\"gk-math\" data-tex=\"q\">q</span>，并判断命题 <span class=\"gk-math\" data-tex=\"q\">q</span> 是真命题还是假命题，说明理由；</li><li>若 <span class=\"gk-math\" data-tex=\"a_{2m}=3^m\">a_{2m}=3^m</span>（<span class=\"gk-math\" data-tex=\"m\\in\\N^*\">m\\in\\N^*</span>），求数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的通项公式.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>当 <span class=\"gk-math\" data-tex=\"n=2\">n=2</span> 时，<span class=\"gk-math\" data-tex=\"i=1\">i=1</span>，所以 <div class=\"gk-math display\" data-tex=\"a_3=2a_2-a_1=2\\times3-1=5\">a_3=2a_2-a_1=2\\times3-1=5</div> 当 <span class=\"gk-math\" data-tex=\"n=3\">n=3</span> 时，<span class=\"gk-math\" data-tex=\"i\">i</span> 可以取 <span class=\"gk-math\" data-tex=\"1\">1</span> 或 <span class=\"gk-math\" data-tex=\"2\">2</span>，故 <div class=\"gk-math display\" data-tex=\"a_4=2a_3-a_i\\in\\{2\\times5-1,2\\times5-3\\}=\\{9,7\\}\">a_4=2a_3-a_i\\in\\{2\\times5-1,2\\times5-3\\}=\\{9,7\\}</div> 所以 <span class=\"gk-math\" data-tex=\"a_4\">a_4</span> 的所有可能值为 <span class=\"gk-math\" data-tex=\"7\">7</span>，<span class=\"gk-math\" data-tex=\"9\">9</span>.</li><li>若 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"a_2\">a_2</span>，<span class=\"gk-math\" data-tex=\"\\ldots\">\\ldots</span>，<span class=\"gk-math\" data-tex=\"a_8\">a_8</span> 成等差数列，则其公差为 <div class=\"gk-math display\" data-tex=\"a_2-a_1=3-1=2\">a_2-a_1=3-1=2</div> 从而 <span class=\"gk-math\" data-tex=\"a_n=2n-1\">a_n=2n-1</span>，<span class=\"gk-math\" data-tex=\"1\\le n\\le8\">1\\le n\\le8</span>. 由递推关系，在 <span class=\"gk-math\" data-tex=\"n=8\">n=8</span> 时存在 <span class=\"gk-math\" data-tex=\"i\\in[1,7]\">i\\in[1,7]</span>，使得 <div class=\"gk-math display\" data-tex=\"a_9=2a_8-a_i=30-(2i-1)=31-2i\\le29&lt;30\">a_9=2a_8-a_i=30-(2i-1)=31-2i\\le29&lt;30</div> 所以命题 <span class=\"gk-math\" data-tex=\"p\">p</span> 是真命题.<br><br>命题 <span class=\"gk-math\" data-tex=\"p\">p</span> 的逆命题为<br><br>“若 <span class=\"gk-math\" data-tex=\"a_9&lt;30\">a_9&lt;30</span>，则 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"a_2\">a_2</span>，<span class=\"gk-math\" data-tex=\"\\ldots\">\\ldots</span>，<span class=\"gk-math\" data-tex=\"a_8\">a_8</span> 成等差数列.”<br><br>该逆命题为假命题. 例如取 <span class=\"gk-math\" data-tex=\"a_1=1\">a_1=1</span>，<span class=\"gk-math\" data-tex=\"a_2=3\">a_2=3</span>，<span class=\"gk-math\" data-tex=\"a_3=5\">a_3=5</span>，<span class=\"gk-math\" data-tex=\"a_4=7\">a_4=7</span>，<span class=\"gk-math\" data-tex=\"a_5=11\">a_5=11</span>，<span class=\"gk-math\" data-tex=\"a_6=15\">a_6=15</span>，<span class=\"gk-math\" data-tex=\"a_7=19\">a_7=19</span>，<span class=\"gk-math\" data-tex=\"a_8=23\">a_8=23</span>，<span class=\"gk-math\" data-tex=\"a_9=27\">a_9=27</span>. 这些数满足 <span class=\"gk-math\" data-tex=\"a_3=2a_2-a_1\">a_3=2a_2-a_1</span>，<span class=\"gk-math\" data-tex=\"a_4=2a_3-a_2\">a_4=2a_3-a_2</span>，<span class=\"gk-math\" data-tex=\"a_5=2a_4-a_2\">a_5=2a_4-a_2</span> <span class=\"gk-math\" data-tex=\"a_6=2a_5-a_4\">a_6=2a_5-a_4</span>，<span class=\"gk-math\" data-tex=\"a_7=2a_6-a_5\">a_7=2a_6-a_5</span>，<span class=\"gk-math\" data-tex=\"a_8=2a_7-a_6\">a_8=2a_7-a_6</span>，<span class=\"gk-math\" data-tex=\"a_9=2a_8-a_7\">a_9=2a_8-a_7</span> 其中每一步所用下标均满足规定范围. 但 <span class=\"gk-math\" data-tex=\"a_4-a_3=2\">a_4-a_3=2</span>，<span class=\"gk-math\" data-tex=\"a_5-a_4=4\">a_5-a_4=4</span>，故前八项不成等差数列，而 <span class=\"gk-math\" data-tex=\"a_9=27&lt;30\">a_9=27&lt;30</span>. 所以逆命题为假命题. 将 <span class=\"gk-math\" data-tex=\"n\\ge9\">n\\ge9</span> 时的后续项定义为 <span class=\"gk-math\" data-tex=\"a_{n+1}=2a_n-a_{n-1}\">a_{n+1}=2a_n-a_{n-1}</span>，则后续每一步取 <span class=\"gk-math\" data-tex=\"i=n-1\">i=n-1</span> 即满足题设递推条件，故上述前九项确实可以延拓为满足题设的数列.</li><li>先证明数列严格递增. 已知 <span class=\"gk-math\" data-tex=\"a_1&lt;a_2\">a_1&lt;a_2</span>. 若 <span class=\"gk-math\" data-tex=\"a_1&lt;a_2&lt;\\cdots&lt;a_n\">a_1&lt;a_2&lt;\\cdots&lt;a_n</span>，则对任意满足条件的 <span class=\"gk-math\" data-tex=\"i&lt;n\">i&lt;n</span>，有 <span class=\"gk-math\" data-tex=\"a_i&lt;a_n\">a_i&lt;a_n</span>，从而 <div class=\"gk-math display\" data-tex=\"a_{n+1}=2a_n-a_i&gt;a_n\">a_{n+1}=2a_n-a_i&gt;a_n</div> 由数学归纳法，数列严格递增.<br><br>记 <span class=\"gk-math\" data-tex=\"b_m=a_{2m-1}\">b_m=a_{2m-1}</span>. 已知 <span class=\"gk-math\" data-tex=\"b_2=a_3=5=5\\times3^0\">b_2=a_3=5=5\\times3^0</span>. 下面用归纳法证明对 <span class=\"gk-math\" data-tex=\"m\\ge2\">m\\ge2</span>，都有 <span class=\"gk-math\" data-tex=\"b_m=5\\times3^{m-2}\">b_m=5\\times3^{m-2}</span>.<br><br>假设 <span class=\"gk-math\" data-tex=\"2\\le r&lt;m\">2\\le r&lt;m</span> 时结论成立. 在 <span class=\"gk-math\" data-tex=\"n=2m-2\">n=2m-2</span> 时，存在 <span class=\"gk-math\" data-tex=\"i\\in[1,2m-3]\">i\\in[1,2m-3]</span>，使得 <div class=\"gk-math display\" data-tex=\"b_m=a_{2m-1}=2a_{2m-2}-a_i=2\\times3^{m-1}-a_i\">b_m=a_{2m-1}=2a_{2m-2}-a_i=2\\times3^{m-1}-a_i</div> 记 <span class=\"gk-math\" data-tex=\"x=a_i\">x=a_i</span>. 再在 <span class=\"gk-math\" data-tex=\"n=2m-1\">n=2m-1</span> 时，由 <span class=\"gk-math\" data-tex=\"a_{2m}=3^m\">a_{2m}=3^m</span>，存在 <span class=\"gk-math\" data-tex=\"j\\in[1,2m-2]\">j\\in[1,2m-2]</span>，使得 <div class=\"gk-math display\" data-tex=\"a_j=2b_m-3^m=3^{m-1}-2x\">a_j=2b_m-3^m=3^{m-1}-2x</div> 记 <span class=\"gk-math\" data-tex=\"y=a_j\">y=a_j</span>，则 <div class=\"gk-math display\" data-tex=\"2x+y=3^{m-1}\">2x+y=3^{m-1}</div> 根据归纳假设，<span class=\"gk-math\" data-tex=\"x\">x</span>，<span class=\"gk-math\" data-tex=\"y\">y</span> 均来自数值集合 <div class=\"gk-math display\" data-tex=\"\\{3^r:0\\le r\\le m-1\\}\\cup\\{5\\times3^s:0\\le s\\le m-3\\}\">\\{3^r:0\\le r\\le m-1\\}\\cup\\{5\\times3^s:0\\le s\\le m-3\\}</div> 逐类考察上式：若 <span class=\"gk-math\" data-tex=\"x\">x</span>，<span class=\"gk-math\" data-tex=\"y\">y</span> 都是 <span class=\"gk-math\" data-tex=\"3\">3</span> 的幂，指数不同时除以较小的幂次后左端模 <span class=\"gk-math\" data-tex=\"3\">3</span> 为 <span class=\"gk-math\" data-tex=\"1\">1</span> 或 <span class=\"gk-math\" data-tex=\"2\">2</span>，不可能等于右端；指数相同时只能有 <span class=\"gk-math\" data-tex=\"2\\times3^r+3^r=3^{m-1}\">2\\times3^r+3^r=3^{m-1}</span>，即 <span class=\"gk-math\" data-tex=\"r=m-2\">r=m-2</span>. 若恰有一个数为 <span class=\"gk-math\" data-tex=\"5\">5</span> 乘以 <span class=\"gk-math\" data-tex=\"3\">3</span> 的幂，指数不同时同样模 <span class=\"gk-math\" data-tex=\"3\">3</span> 矛盾，指数相同时左端系数为 <span class=\"gk-math\" data-tex=\"7\">7</span> 或 <span class=\"gk-math\" data-tex=\"11\">11</span>，也不可能是 <span class=\"gk-math\" data-tex=\"3\">3</span> 的幂. 若两个数都为 <span class=\"gk-math\" data-tex=\"5\">5</span> 乘以 <span class=\"gk-math\" data-tex=\"3\">3</span> 的幂，指数不同时模 <span class=\"gk-math\" data-tex=\"3\">3</span> 矛盾，指数相同时左端系数为 <span class=\"gk-math\" data-tex=\"15\">15</span>，仍不可能是 <span class=\"gk-math\" data-tex=\"3\">3</span> 的幂. 因此只能有 <div class=\"gk-math display\" data-tex=\"x=y=3^{m-2}\">x=y=3^{m-2}</div> 于是 <div class=\"gk-math display\" data-tex=\"b_m=2\\times3^{m-1}-3^{m-2}=5\\times3^{m-2}\">b_m=2\\times3^{m-1}-3^{m-2}=5\\times3^{m-2}</div> 归纳得 <span class=\"gk-math\" data-tex=\"a_{2m-1}=5\\times3^{m-2}\">a_{2m-1}=5\\times3^{m-2}</span>（<span class=\"gk-math\" data-tex=\"m\\ge2\">m\\ge2</span>）.<br><br>因此数列通项为 <div class=\"gk-math display\" data-tex=\"a_n=\\begin{cases}\n1,&amp;n=1,\\\\\n3^m,&amp;n=2m,\\ m\\in\\N^*,\\\\\n5\\times3^{m-2},&amp;n=2m-1,\\ m\\ge2.\n\\end{cases}\">a_n=\\begin{cases}\n1,&amp;n=1,\\\\\n3^m,&amp;n=2m,\\ m\\in\\N^*,\\\\\n5\\times3^{m-2},&amp;n=2m-1,\\ m\\ge2.\n\\end{cases}</div> 最后验证该通项确实满足题设递推关系. 先有 <span class=\"gk-math\" data-tex=\"a_3=2a_2-a_1=5\">a_3=2a_2-a_1=5</span>，且 <span class=\"gk-math\" data-tex=\"a_4=2a_3-a_1=9=3^2\">a_4=2a_3-a_1=9=3^2</span>. 当 <span class=\"gk-math\" data-tex=\"m\\ge3\">m\\ge3</span> 时，取 <span class=\"gk-math\" data-tex=\"i=2m-4\">i=2m-4</span>，则 <div class=\"gk-math display\" data-tex=\"a_{2m-1}=2a_{2m-2}-a_{2m-4}=2\\times3^{m-1}-3^{m-2}=5\\times3^{m-2}\">a_{2m-1}=2a_{2m-2}-a_{2m-4}=2\\times3^{m-1}-3^{m-2}=5\\times3^{m-2}</div> 同样，当 <span class=\"gk-math\" data-tex=\"m\\ge3\">m\\ge3</span> 时，在 <span class=\"gk-math\" data-tex=\"n=2m-1\">n=2m-1</span> 的递推中取 <span class=\"gk-math\" data-tex=\"i=2m-4\">i=2m-4</span>，有 <div class=\"gk-math display\" data-tex=\"a_{2m}=2a_{2m-1}-a_{2m-4}=2\\times5\\times3^{m-2}-3^{m-2}=3^m\">a_{2m}=2a_{2m-1}-a_{2m-4}=2\\times5\\times3^{m-2}-3^{m-2}=3^m</div> 当 <span class=\"gk-math\" data-tex=\"m\\ge2\">m\\ge2</span> 时，在 <span class=\"gk-math\" data-tex=\"n=2m\">n=2m</span> 的递推中取 <span class=\"gk-math\" data-tex=\"i=2m-2\">i=2m-2</span>，有 <div class=\"gk-math display\" data-tex=\"a_{2m+1}=2a_{2m}-a_{2m-2}=2\\times3^m-3^{m-1}=5\\times3^{m-1}\">a_{2m+1}=2a_{2m}-a_{2m-2}=2\\times3^m-3^{m-1}=5\\times3^{m-1}</div> 上述各式中所取下标均满足 <span class=\"gk-math\" data-tex=\"1\\le i\\le n-1\">1\\le i\\le n-1</span>，并覆盖 <span class=\"gk-math\" data-tex=\"n\\ge2\">n\\ge2</span> 的全部情形，因此该通项与题设递推关系一致.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]}];
